#!/usr/bin/env python3
"""MOAI-CPU m7_phase_split: port of the moai_waterfall/palma_campaign bootstrap-key phase split onto m6.
~62 GB bootstrap Galois key set split into 3 phases on disk, loaded one at a time during the
bootstrap linear transform; ~1/3 resident (~-43 GB). test_full_scheme.hpp only, project rebuild.
Adapted for glibc (malloc_trim) and this fork (no util::MemoryPoolThresholdMT; keys load under the
global threshold). Gate must stay bitwise m0.

    patch_phase_split.py <moai source root>
"""
import os, sys

SRC = "include/test/test_full_scheme.hpp"
ANCHORS = [
    ('void all_layer_test(){\n', '\n\n// ===== SNNI m7 phase_split (ported from moai_waterfall/palma_campaign; adapted for glibc + our SEAL fork) =====\n#include <fstream>\n#include <set>\n#include <cmath>\n#include <sys/stat.h>\n#include <malloc.h>\n#include <omp.h>\n#include <stdexcept>\n\nstatic void jemalloc_purge_all() { malloc_trim(0); }\nstatic void cleanup_main_log_rss(const string &) {}\nstatic void dump_live_breakdown(const string &) {}\nstatic void probe_with_trim(const string &) {}\nstatic int cleanup_bootstrap_threads() { return omp_get_max_threads(); }\nstatic int cleanup_bootstrap_cts3_threads() { return omp_get_max_threads(); }\n\nstatic string get_work_dir() {\n    const char *v = getenv("MOAI_WORK_DIR");\n    return v ? string(v) : string(".");\n}\nstatic const string phase_key_dir = get_work_dir() + "/phase_keys";\n\nstatic bool phase_file_exists(const string &path) {\n    ifstream in(path, ios::binary);\n    return in.good();\n}\n\nstatic MemoryPoolHandle stage_boot_pool;\n\nstatic void log_pool(const string& label, const MemoryPoolHandle& pool) {\n    if (!pool) { cout << "[POOL] " << label << " <uninitialized>" << endl; return; }\n    cout << "[POOL] " << label\n         << " pool_count=" << pool.pool_count()\n         << " alloc_MiB=" << pool.alloc_byte_count()/(1024*1024)\n         << " use_count=" << pool.use_count() << endl;\n}\n\nstatic void stage_free_galois_keys(GaloisKeys &keys) { keys = GaloisKeys(); malloc_trim(0); }\nstatic void stage_release_pool(MemoryPoolHandle &pool) { pool = MemoryPoolHandle(); malloc_trim(0); }\n\nstatic string stage_boot_phase_path(int phase) {\n    return phase_key_dir + "/boot_phase_" + to_string(phase) + ".keys";\n}\n\nstatic int stage_giantstep(int M) {\n    int minval = M;\n    int mink = 1;\n    for (int k = 1; k <= (int)(3 * sqrt((double)M)); k++) {\n        int currval = (int)ceil((double)M / k) + k - 1;\n        if (currval < minval) {\n            minval = currval;\n            mink = k;\n        }\n    }\n    return mink;\n}\n\nstatic vector<int> stage_boot_phase_steps(int phase, int logn, int logNh) {\n    int Nh = 1 << logNh;\n    int dp1 = (int)floor(logn / 3.0);\n    int dp2 = (int)floor((logn - dp1) / 2.0);\n    int dp3 = logn - dp1 - dp2;\n\n    vector<int> steps;\n    steps.push_back(0);\n\n    auto add_unique = [&](int pos) {\n        int step = (pos > Nh / 2) ? (pos - Nh) : pos;\n        if (step != 0 && find(steps.begin(), steps.end(), step) == steps.end()) {\n            steps.push_back(step);\n        }\n    };\n\n    if (phase == 0) {\n        int totlen = (1 << dp1) - 1;\n        int basicstep = 1 << (logn - dp1);\n        int gs = stage_giantstep(totlen + 1);\n        for (int i = 1; i < gs; i++) {\n            add_unique((Nh + i * basicstep) % Nh);\n        }\n        int giantlast = (int)floor((double)totlen / gs);\n        for (int i = 1; i <= giantlast; i++) {\n            add_unique((i * gs * basicstep) % Nh);\n        }\n    } else if (phase == 1) {\n        int totlen = (1 << dp2) - 1;\n        int basicstep = 1 << (logn - dp1 - dp2);\n        int gs = stage_giantstep(2 * totlen + 1);\n        int bs0 = -totlen + gs * (int)floor((double)totlen / gs);\n        for (int i = bs0; i < bs0 + gs; i++) {\n            if (i != 0) add_unique((Nh + i * basicstep) % Nh);\n        }\n        int gf = -(int)floor((double)totlen / gs);\n        int gl = (int)floor((double)(2 * totlen) / gs) + gf;\n        for (int i = gf; i <= gl; i++) {\n            if (i != 0) add_unique((Nh + i * gs * basicstep) % Nh);\n        }\n    } else {\n        int totlen = (1 << dp3) - 1;\n        int basicstep = 1;\n        int gs = stage_giantstep(2 * totlen + 1);\n        int bs0 = -totlen + gs * (int)floor((double)totlen / gs);\n        for (int i = bs0; i < bs0 + gs; i++) {\n            if (i != 0) add_unique((Nh + i * basicstep) % Nh);\n        }\n        int gf = -(int)floor((double)totlen / gs);\n        int gl = (int)floor((double)(2 * totlen) / gs) + gf;\n        for (int i = gf; i <= gl; i++) {\n            if (i != 0) add_unique((Nh + i * gs * basicstep) % Nh);\n        }\n    }\n\n    return steps;\n}\n\nstatic void stage_save_boot_phase_keys(KeyGenerator &keygen, const SEALContext &context, int logn, int logNh) {\n    auto &context_data = *context.key_context_data();\n    auto galois_tool = context_data.galois_tool();\n    size_t coeff_count = context_data.parms().poly_modulus_degree();\n\n    for (int phase = 0; phase < 3; phase++) {\n        vector<int> steps = stage_boot_phase_steps(phase, logn, logNh);\n        GaloisKeys phase_keys;\n        phase_keys.data().resize(coeff_count);\n        phase_keys.parms_id() = context_data.parms_id();\n\n        std::set<uint32_t> seen;\n        for (int step : steps) {\n            uint32_t elt = (step == 0)\n                ? static_cast<uint32_t>(coeff_count * 2 - 1)\n                : galois_tool->get_elt_from_step(step);\n            if (seen.count(elt)) {\n                continue;\n            }\n            seen.insert(elt);\n\n            GaloisKeys single;\n            keygen.create_galois_keys(vector<int>{step}, single);\n            size_t index = GaloisKeys::get_index(elt);\n            phase_keys.data()[index] = move(single.data()[index]);\n            single = GaloisKeys();\n            malloc_trim(0);\n        }\n\n        cleanup_main_log_rss(string("boot_phase_") + to_string(phase) + "_created");\n        string path = stage_boot_phase_path(phase);\n        cout << "Saving boot phase " << phase << " keys (" << seen.size() << " elements) to " << path << endl;\n        ofstream out(path, ios::binary);\n        if (!out) {\n            throw runtime_error("failed to open boot phase key output: " + path);\n        }\n        phase_keys.save(out, compr_mode_type::none);\n        phase_keys = GaloisKeys();\n        malloc_trim(0);\n        cleanup_main_log_rss(string("boot_phase_") + to_string(phase) + "_freed");\n    }\n}\n\n\n// stage_load_boot_phase ADAPTED: our SEAL fork has NO util::MemoryPoolThresholdMT (only the palma fork\n// does). Our GLOBAL default is already the threshold recording pool, so load the phase keys under it\n// directly -- no scoped pool switch. Free the previous phase\'s keys first.\nstatic void stage_load_boot_phase(int phase, Bootstrapper &bootstrapper, MemoryPoolHandle &pool) {\n    (void)pool;\n    stage_free_galois_keys(bootstrapper.gal_keys);\n    string path = stage_boot_phase_path(phase);\n    ifstream in(path, ios::binary);\n    if (!in) { throw runtime_error("failed to open boot phase key input: " + path); }\n    bootstrapper.gal_keys.load(bootstrapper.context, in);\n    malloc_trim(0);\n    { static bool _snni_o=false; if(!_snni_o){_snni_o=true; fprintf(stderr,"LEVER|phase_split|boot_phase_streaming\\n"); fflush(stderr);} }\n}\n\nstatic void stage_bootstrap_batch_split(Bootstrapper &bs, vector<Ciphertext> &rtn,\n                                        vector<Ciphertext> &input, int count,\n                                        const string &stage_name) {\n    int logn = bs.logn;\n    int dp1 = (int)floor(logn / 3.0);\n    int dp2 = (int)floor((logn - dp1) / 2.0);\n    int dp3 = logn - dp1 - dp2;\n    int tl1 = (1 << dp1) - 1;\n    int tl2 = (1 << dp2) - 1;\n    int tl3 = (1 << dp3) - 1;\n    int bs1_inv = 1 << (logn - dp1);\n    int bs2_inv = 1 << (logn - dp1 - dp2);\n    int bs3_inv = 1;\n\n    int dp3f = (int)floor(logn / 3.0);\n    int dp2f = (int)floor((logn - dp3f) / 2.0);\n    int dp1f = logn - dp3f - dp2f;\n    int tl1f = (1 << dp1f) - 1;\n    int tl2f = (1 << dp2f) - 1;\n    int tl3f = (1 << dp3f) - 1;\n    int bs1_fwd = 1;\n    int bs2_fwd = 1 << dp1f;\n    int bs3_fwd = 1 << (dp1f + dp2f);\n\n    const auto &modulus = iter(bs.context.first_context_data()->parms().coeff_modulus());\n\n    vector<double> initial_scales(count);\n    cleanup_main_log_rss(stage_name + "_stage_modraise_begin");\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        initial_scales[i] = input[i].scale();\n        bs.modraise_inplace(input[i]);\n        input[i].scale() = (double)modulus[0].value();\n    }\n    cleanup_main_log_rss(stage_name + "_stage_modraise_done");\n\n    // CTS1/CTS2 use MMProfNew (global default) — brief jemalloc spikes are OK\n    stage_load_boot_phase(0, bs, stage_boot_pool);\n    vector<Ciphertext> cts1(count);\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        bs.rotated_bsgs_linear_transform(cts1[i], input[i], tl1, bs1_inv, logn, bs.invfftcoeff1[bs.slot_index]);\n        bs.evaluator.rescale_to_next_inplace(cts1[i]);\n        input[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(input);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_cts1_done");\n\n    stage_load_boot_phase(1, bs, stage_boot_pool);\n    vector<Ciphertext> cts2(count);\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        bs.bsgs_linear_transform(cts2[i], cts1[i], tl2, bs2_inv, logn, bs.invfftcoeff2[bs.slot_index]);\n        bs.evaluator.rescale_to_next_inplace(cts2[i]);\n        cts1[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(cts1);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_cts2_done");\n\n    // [04j] CTS3: MMProfNew (global default) — mimalloc handles purge via\n    // MADV_DONTNEED. No shared pool needed (shared pools retain free lists\n    // that inflate RSS during subsequent phases).\n    stage_load_boot_phase(2, bs, stage_boot_pool);\n    vector<Ciphertext> cts3(count);\n    #pragma omp parallel for num_threads(cleanup_bootstrap_cts3_threads())\n    for (int i = 0; i < count; i++) {\n        bs.bsgs_linear_transform(cts3[i], cts2[i], tl3, bs3_inv,\n                                 logn + 1, bs.invfftcoeff3[bs.slot_index]);\n        bs.evaluator.rescale_to_next_inplace(cts3[i]);\n        cts2[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(cts2);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_cts3_post_transform");\n\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        Ciphertext conj;\n        bs.evaluator.complex_conjugate(cts3[i], bs.gal_keys, conj);\n        bs.evaluator.add_inplace_reduced_error(cts3[i], conj);\n    }\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_cts3_post_conjugate");\n    cleanup_main_log_rss(stage_name + "_stage_cts3_done");\n\n    // Modred, STC1-3: use MMProfNew (global default). Brief jemalloc spikes\n    // are acceptable for these short phases. Per-phase pools DON\'T work here\n    // because output CTs hold pool refs → pool free list accumulates.\n    cleanup_main_log_rss(stage_name + "_stage_modred_alloc_begin");\n    // EXP21: full breakdown right before modred temp pool is allocated.\n    // This is the most useful probe — the 33 GiB modred temp comes immediately after.\n    dump_live_breakdown(stage_name + "_pre_modred");\n    vector<Ciphertext> modrtn(count);\n    cleanup_main_log_rss(stage_name + "_stage_modred_alloc_ready");\n    dump_live_breakdown(stage_name + "_post_modred_alloc");\n    probe_with_trim(stage_name + "_post_modred_alloc");\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        bs.mod_reducer->modular_reduction(modrtn[i], cts3[i]);\n        cts3[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(cts3);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_modred_done");\n\n    vector<Ciphertext> stc1(count);\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        bs.bsgs_linear_transform(stc1[i], modrtn[i], tl1f, bs1_fwd, logn, bs.fftcoeff1[bs.slot_index]);\n        bs.evaluator.rescale_to_next_inplace(stc1[i]);\n        modrtn[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(modrtn);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_stc1_done");\n\n    stage_load_boot_phase(1, bs, stage_boot_pool);\n    vector<Ciphertext> stc2(count);\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        bs.bsgs_linear_transform(stc2[i], stc1[i], tl2f, bs2_fwd, logn, bs.fftcoeff2[bs.slot_index]);\n        bs.evaluator.rescale_to_next_inplace(stc2[i]);\n        stc1[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(stc1);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_stc2_done");\n\n    stage_load_boot_phase(0, bs, stage_boot_pool);\n    rtn.resize(count);\n    cleanup_main_log_rss(stage_name + "_stage_stc3_alloc_ready");\n    #pragma omp parallel for num_threads(cleanup_bootstrap_threads())\n    for (int i = 0; i < count; i++) {\n        auto chain_index = bs.context.get_context_data(stc2[i].parms_id())->chain_index();\n        double mod_zero = (double)modulus[0].value();\n        double curr_mod = (double)modulus[chain_index].value();\n        vector<vector<complex<double>>> fftcoeff3_scale(tl3f + 1);\n        for (int a = 0; a < tl3f + 1; a++) {\n            fftcoeff3_scale[a].resize(bs.n);\n            for (int b = 0; b < bs.n; b++) {\n                fftcoeff3_scale[a][b] = bs.fftcoeff3[bs.slot_index][a][b]\n                    * curr_mod * mod_zero * bs.final_scale\n                    / (stc2[i].scale() * stc2[i].scale() * initial_scales[i]);\n            }\n        }\n        if (i == 0) {\n            cleanup_main_log_rss(stage_name + "_stage_stc3_coeff_expand_active");\n        }\n        bs.rotated_bsgs_linear_transform(rtn[i], stc2[i], tl3f, bs3_fwd, logn, fftcoeff3_scale);\n        bs.evaluator.rescale_to_next_inplace(rtn[i]);\n        rtn[i].scale() = bs.final_scale;\n        stc2[i] = Ciphertext();\n    }\n    vector<Ciphertext>().swap(stc2);\n    jemalloc_purge_all();\n    cleanup_main_log_rss(stage_name + "_stage_stc3_done");\n}\n\n// ===== end SNNI m7 phase_split =====\n\nvoid all_layer_test(){\n'),
    ('    //cout << "Adding Bootstrapping Keys..." << endl;\n    vector<int> gal_steps_vector;\n    gal_steps_vector.push_back(0);\n    for (int i = 0; i < logN - 1; i++) {\n        gal_steps_vector.push_back((1 << i));\n    }\n    bootstrapper.addLeftRotKeys_Linear_to_vector_3(gal_steps_vector);\n\n    keygen.create_galois_keys(gal_steps_vector, gal_keys_boot);\n', '    // SNNI m7 phase_split: the full gal_keys_boot (~62 GB) generation is REMOVED here; the 3\n    // key phases are generated + saved after generate_LT_coefficient_3 and loaded one at a time.\n'),
    ('  bootstrapper.generate_LT_coefficient_3();\n', '  bootstrapper.generate_LT_coefficient_3();\n  // SNNI m7 phase_split: generate + save the 3 bootstrap key phases to disk.\n  ::mkdir(phase_key_dir.c_str(), 0777);\n  if (phase_file_exists(stage_boot_phase_path(0)) &&\n      phase_file_exists(stage_boot_phase_path(1)) &&\n      phase_file_exists(stage_boot_phase_path(2))) {\n      cout << "Reusing stage-split bootstrap keys from " << phase_key_dir << endl;\n  } else {\n      cout << "saving stage-split bootstrap keys..." << endl;\n      stage_save_boot_phase_keys(keygen, context, logn, logN - 1);\n  }\n'),
    ('    #pragma omp parallel for\n\n    for(int i = 0 ; i < 128 ; ++i){\n        for(int j = 0 ; j < 6 ; ++j){\n            bootstrapper.bootstrap_3(rtn[i*6+j],att_selfoutput[i*6+j]);\n        }\n    }\n', '    stage_bootstrap_batch_split(bootstrapper, rtn, att_selfoutput, 768, "bootstrap1");\n'),
    ('    #pragma omp parallel for\n\n    for(int i = 0 ; i < 128 ; ++i){\n        for(int j = 0 ; j < 6 ; ++j){\n            bootstrapper.bootstrap_3(rtn[i*6+j],layernorm_selfoutput[i*6+j]);\n            boot_layer[i*6+j] = rtn[i*6+j];\n        }\n    }\n', '    stage_bootstrap_batch_split(bootstrapper, rtn, layernorm_selfoutput, 768, "bootstrap2");\n    for(int _k=0;_k<768;++_k){ boot_layer[_k] = rtn[_k]; }\n'),
    ('    #pragma omp parallel for\n\n    for(int i = 0 ; i < 128 ; ++i){\n        for(int j = 0 ; j < 6 ; ++j){\n            bootstrapper.bootstrap_3(rtn2[i*6+j],final_output[i*6+j]);\n        }\n    }\n', '    stage_bootstrap_batch_split(bootstrapper, rtn2, final_output, 768, "bootstrap3");\n'),
    ('    #pragma omp parallel for\n\n    for(int i = 0 ; i < 128 ; ++i){\n        for(int j = 0 ; j < 6 ; ++j){\n            bootstrapper.bootstrap_3(rtn2[i*6+j],layernorm_finaloutput[i*6+j]);\n            enc_ecd_x[i*6+j] = rtn2[i*6+j];\n            enc_ecd_x_copy[i*6+j] = rtn2[i*6+j];\n        }\n    }\n', '    stage_bootstrap_batch_split(bootstrapper, rtn2, layernorm_finaloutput, 768, "bootstrap4");\n    for(int _k=0;_k<768;++_k){ enc_ecd_x[_k] = rtn2[_k]; enc_ecd_x_copy[_k] = rtn2[_k]; }\n')
]

def main():
    if len(sys.argv) != 2: sys.exit(__doc__)
    src = os.path.join(sys.argv[1], SRC)
    if not os.path.exists(src): sys.exit("FAILED: no " + SRC)
    txt = open(src).read()
    if "phase_split" in txt: sys.exit("FAILED: tree already carries phase_split")
    for i,(f,t) in enumerate(ANCHORS):
        if txt.count(f) != 1: sys.exit(f"FAILED: anchor {i} matched {txt.count(f)} (want 1)")
    for f,t in ANCHORS:
        txt = txt.replace(f, t, 1)
    open(src,"w").write(txt)
    out = open(src).read()
    for need in ("stage_bootstrap_batch_split(bootstrapper, rtn, att_selfoutput",
                 "stage_save_boot_phase_keys(keygen, context, logn, logN - 1)",
                 "LEVER|phase_split", "static void stage_bootstrap_batch_split",
                 "boot_layer[_k] = rtn[_k]", "enc_ecd_x_copy[_k] = rtn2[_k]"):
        if need not in out: sys.exit(f"FAILED: post-check absent: {need!r}")
    if "bootstrapper.bootstrap_3(" in out: sys.exit("FAILED: a monolithic bootstrap_3 call survived")
    if "make_shared<util::MemoryPoolThresholdMT>" in out: sys.exit("FAILED: MemoryPoolThresholdMT instantiated (missing in our fork)")
    if "create_galois_keys(gal_steps_vector" in out: sys.exit("FAILED: full gal_keys_boot generation survived")
    print("patch_phase_split: applied (" + SRC + ")")

if __name__ == "__main__": main()
